(function(){
  // epub.min.js placeholder loader
  // This small file loads the real epub.js library from a CDN at runtime.
  // It keeps the repo lightweight while allowing index.html to reference ./epub.min.js
  
  var CDN_URLS = [
    'https://cdn.jsdelivr.net/npm/epubjs@0.3.88/dist/epub.min.js',
    'https://unpkg.com/epubjs@0.3.88/dist/epub.min.js'
  ];

  function tryLoad(urls, i) {
    if (i >= urls.length) {
      console.error('epub.min.js placeholder: all CDN sources failed to load.');
      return;
    }
    var s = document.createElement('script');
    s.src = urls[i];
    s.crossOrigin = 'anonymous';
    s.onload = function(){
      console.log('epub.min.js loader: loaded from ' + urls[i]);
    };
    s.onerror = function(){
      console.warn('epub.min.js loader: failed to load from ' + urls[i] + ', trying next...');
      tryLoad(urls, i+1);
    };
    document.head.appendChild(s);
  }

  tryLoad(CDN_URLS, 0);
})();
